import { passkeyPrfSaltEntries, unwrapVmk } from "./vaultCrypto"
import { commitUnlockedVmk, rememberWrapMeta } from "./vaultLifecycle"
import { assertPasskeyPrf } from "./webauthn"
import { type VaultSessionPolicy } from "./policy"

export type ApprovalUnlockResult = {
  state: "unlocked"
  rpId: string
  expiresAt: number
}

export type ApprovalUnlockAssertion = {
  prfOutput: Uint8Array
  prfSalt: Uint8Array
}

function abortReason(signal: AbortSignal): Error {
  const reason = (signal as AbortSignal & { reason?: unknown }).reason
  return reason instanceof Error ? reason : new Error("operation-superseded")
}

function rejectOnAbort(signal: AbortSignal): Promise<never> {
  return new Promise((_, reject) => {
    const abort = (): void => reject(abortReason(signal))
    if (signal.aborted) {
      abort()
      return
    }
    signal.addEventListener("abort", abort, { once: true })
  })
}

function throwIfAborted(signal?: AbortSignal): void {
  if (signal?.aborted) throw abortReason(signal)
}

export async function unlockVmkFromPasskeyPrf(input: {
  wrapMeta: string
  currentRpId: string
  abortSignal?: AbortSignal
  policy?: VaultSessionPolicy
}): Promise<ApprovalUnlockResult> {
  const remembered = rememberWrapMeta(input.wrapMeta)
  const entries = passkeyPrfSaltEntries(remembered.wrapMeta)
  let prfOutput: Uint8Array | undefined
  let vmk: Uint8Array | undefined
  try {
    const assertion = await Promise.race([
      assertPasskeyPrf(entries, input.currentRpId, input.abortSignal).then(
        (result) => {
          if (input.abortSignal?.aborted) {
            result.prfOutput.fill(0)
            throw abortReason(input.abortSignal)
          }
          return result
        },
        (error) => {
          if (input.abortSignal?.aborted) throw abortReason(input.abortSignal)
          throw error
        },
      ),
      ...(input.abortSignal ? [rejectOnAbort(input.abortSignal)] : []),
    ])
    prfOutput = assertion.prfOutput
    return await unlockVmkFromPasskeyPrfAssertion({
      wrapMeta: remembered.wrapMeta,
      currentRpId: input.currentRpId,
      assertion,
      ...(input.abortSignal ? { abortSignal: input.abortSignal } : {}),
      ...(input.policy ? { policy: input.policy } : {}),
    })
  } finally {
    prfOutput?.fill(0)
    vmk?.fill(0)
  }
}

export async function unlockVmkFromPasskeyPrfAssertion(input: {
  wrapMeta: string
  currentRpId: string
  assertion: ApprovalUnlockAssertion
  abortSignal?: AbortSignal
  policy?: VaultSessionPolicy
}): Promise<ApprovalUnlockResult> {
  const remembered = rememberWrapMeta(input.wrapMeta)
  let vmk: Uint8Array | undefined
  try {
    throwIfAborted(input.abortSignal)
    vmk = await unwrapVmk(remembered.wrapMeta, {
      kind: "passkey",
      prfOutput: input.assertion.prfOutput,
      prfSalt: input.assertion.prfSalt,
    })
    throwIfAborted(input.abortSignal)
    const unlocked = commitUnlockedVmk({
      vmk,
      wrapMeta: remembered.wrapMeta,
      freshSetup: false,
      scopeId: remembered.scopeId,
      ...(input.policy ? { policy: input.policy } : {}),
    })
    vmk = undefined
    return { state: unlocked.state, rpId: input.currentRpId, expiresAt: unlocked.expiresAt }
  } finally {
    input.assertion.prfOutput.fill(0)
    vmk?.fill(0)
  }
}
